+
+        request = new UpdateByQueryRequest();
+        request.getSearchRequest().source().version(false);
+        assertFalse(action().mainRequest.getSearchRequest().source().version());
+
+        request = new UpdateByQueryRequest();
+        request.getSearchRequest().source().version(null);
