+            hasDiscoveredQuorum,
+            new StatusInfo(randomFrom(StatusInfo.Status.HEALTHY, StatusInfo.Status.UNHEALTHY), randomAlphaOfLength(20)),
+            Collections.emptyList()
+        );
+    }
